"""Exposure, uncertainty and oracle headroom for every available graph checkpoint."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parent
def load(n):return json.loads((ROOT/n).read_bytes())
def num(x,n=2):return f"{x:.{n}f}".replace(".",",")
def interval(v):return num(100*v["delta"])+" ["+num(100*v["ci"][0])+"; "+num(100*v["ci"][1])+"]"


def generate():
    panels=[tag for tag in ("hash64","availability","canonical") if (ROOT/f"{tag}-results.json").is_file()]
    d=["# Когда стоит запускать графовый ранжировщик","",
       "Исследуем решение, принимаемое после дешёвого ранжирования PU Dense-FT и до расчёта residual R-GCN. На 500 dev-запросах Ridge с alpha=25 обучается предсказывать, позволит ли граф при том же бюджете 2 048 токенов прочитать все эталонные символы. Для каждого test-запроса модель видит только сам вопрос и доступную до графа структуру и оценки плотного ранжирования. Порог фиксируется по dev. Первичное условие успеха допускает до 60% реальных решений вызвать граф и требует нижнюю границу парного 95% ДИ для разницы FS выше −1,00 п.п. относительно применения графа на всех запросах. [Исходный протокол](PROTOCOL_RU.md) · [Особенности CPU-панелей](CPU_PANELS_RU.md)",""]
    if not panels:
        d+=["Запечатаны 500 строк dev и 2 000 строк test c признаками, включая контрольные суммы исходных кандидатов. Для чисел качества нужны опубликованные владельцем отдельно зафиксированные dev/test-ранги соответствующего графового чекпойнта. [Фиксация признаков](feature-seal.json)"]
    for tag in panels:
        r=load(tag+"-results.json");p=load(tag+"-model.json");s=r["stats"];c=r["paired"];k=r["primary"]
        d+=[f"## {tag}","",f"При номинальном бюджете 50% политика запрашивает граф в **{s['gate50']['calls']}/2 000** случаях ({num(100*k['rate'])}%). Полный support получен для **{s['gate50']['fs']}** вопросов при использовании политики и {s['always_graph']['fs']} при всегда включённом графе. Δ FS, п.п. [95% ДИ] — {interval(c['gate50-always_graph']['metric']['fs'])}. Нижняя граница должна быть строго выше −1,00. Общее заранее заданное условие {'выполнено' if k['met'] else 'не выполнено'}.","",
           "| Метод | Граф вызван | FS, случаев / 2 000 | Coverage, % | Вызовы с выигрышем FS | Вызовы с потерей FS |",
           "|---|---:|---:|---:|---:|---:|"]
        for method in ["always_dense","always_graph","gate25","margin25","random25","oracle25","gate50","margin50","random50","oracle50","gate75","margin75","random75","oracle75"]:
            v=s[method];d.append(f"| {method} | {v['calls']} | {v['fs']} | {num(100*v['coverage'])} | {v['benefit_calls']} | {v['harm_calls']} |")
        oracle=r["oracles"];strong=sorted(zip(load("plan.json")["features"],p["coef"]),key=lambda x:-abs(x[1]))[:4]
        d+=["",f"На 500 калибровочных запросах отдельно граф давал FS в {p['dev_graph']} случаях, Dense-FT — в {p['dev_dense']}. Наибольшие по модулю стандартизованные коэффициенты Ridge: "+", ".join(f"{n} = {num(v,4)}" for n,v in strong)+". Это коэффициенты линейной ассоциации с различием двух ранжировщиков для этого чекпойнта.","",
            f"На test только граф достиг полного покрытия в {oracle['graph_only']} вопросах, только плотная модель — в {oracle['dense_only']}. Идеальный маршрутизатор, принимающий решение при знании gold FS, имеет потолок {oracle['unconstrained']}/2 000. Варианты oracle в таблице оценивают потолок FS с точно тем же числом вызовов, что gate. Среди равных дельт FS критерии Coverage/Density не оптимизировались. SHA-контроль random также совпадает с фактическим числом вызовов, margin отдельно калибруется до теста, поэтому его доля может быть другой.","",
            f"При 50% gate−random по FS составляет {interval(c['gate50-random50']['metric']['fs'])} п.п.; gate−margin — {interval(c['gate50-margin50']['metric']['fs'])} п.п. Парные интервалы основаны на 10 000 выборках целых траекторий. На одной модели и общем test они отражают вариацию запросов при фиксированном обучении. [Поштучные результаты]("+tag+"-outcomes.json.gz) · [Все контрасты]("+tag+"-results.json) · [Решения до оценивания]("+tag+"-decision-seal.json)",""]
        if (ROOT/f"{tag}-controls.json").exists():
            ctl=load(f"{tag}-controls.json")["panels"]
            d+=["В дополнительной проверке ту же границу −1,00 п.п. и потолок доли обращений применили к простым контролям. "
                +" ".join(f"{a}: Δ FS {interval(ctl[a]['fs'])} п.п., условие "+("выполнено." if ctl[a]["met"] else "не выполнено.") for a in ["always_dense","random50","margin50"])
                +" [Сравнение с постоянно используемым графом]("+tag+"-controls.json)",""]
    if (ROOT/"transfer-source-receipt.json").exists():
        overlap=load("transfer-source-receipt.json")
        d+=["## Перенос после исключения дословных совпадений источников","",
            f"Поле test с эталонной цитатой целиком встречалось среди входных полей 500 dev-запросов у {overlap['dev_field_match']} вопросов из 2 000. Такие совпадения с train плотной модели обнаружены у 125 вопросов, с обеими выборками одновременно — у {overlap['both']}. Контроль использует ранее запечатанные решения и прежний критерий. [Детали проверки точных повторов](TRANSFER_RU.md)","",
            "| Модель | Исключены совпадения с | N | Вызовы | FS gate / graph | Разность FS, п.п. [95% ДИ] | Критерий |",
            "|---|---|---:|---:|---:|---:|---|"]
        for path in sorted(ROOT.glob("*-source-transfer.json")):
            subset=load(path.name)["panels"]
            for key,label in (("omit_dev_matches","dev"),("omit_train_and_dev_matches","train и dev")):
                item=subset[key]
                d.append(f"| {path.name.split('-')[0]} | {label} | {item['n']} | {item['calls']} | {item['gate']} / {item['graph']} | {interval(item['paired_fs'])} | "+("выполнен" if item["criterion"] else "не выполнен")+" |")
        d.append("")
    timing=load("feature-seal.json")["seconds"]
    d+=["## Стоимость и пределы вывода","",
       f"Извлечение и фиксация дешёвых признаков заняли в этой реализации {num(timing['test'],1)} с на 2 000 test-запросов и {num(timing['dev'],1)} с на 500 dev, включая чтение проекций и контрольные хеши кандидатов. Плотное ранжирование предполагается уже готовым и также имеет цену. Для офлайн-сопоставления оба ранжировщика рассчитаны на каждом тестовом вопросе. Эксперимент оценивает долю условных запусков, а не сквозное ускорение системы. При пакетном выполнении и совместном кэшировании время в общем случае не пропорционально доле вызовов. Для сравнения с полноразмерной опубликованной R-GCN нужны соответствующие веса и режим обучения. [Воспроизведение](REPRODUCE_RU.md)"]
    d+=["","### Измеренное время остаточной графовой стадии","",
        "На 96 запросах, выбранных по хешу, выполнены четыре парных повтора после прогрева на одном CPU-потоке, batch=1, FP32. Таймер включает сборку батча из кэшированных тензоров и реальный прямой проход графовой сети. Вариант Ridge дополнительно выполняет проверку порога на каждом запросе. Кодирование и извлечение числовых признаков из первого ранжирования выполнялись отдельно. [Протокол и границы измерений](RUNTIME_RU.md)","",
        "| Модель | Вызовы | Время always, с, 4 повтора | Время gate, с, 4 повтора | Медиана gate/always | Совпал порядок top-10 с пакетным расчётом |",
        "|---|---:|---|---|---:|---:|"]
    for path in sorted(ROOT.glob("*-runtime.json")):
        t=load(path.name);pairs=t["pairs"]
        timings=lambda arm:" / ".join(num(v[arm]["seconds"],2) for v in pairs)
        d.append(f"| {path.name[:-13]} | {pairs[0]['gate']['calls']} / {t['n']} | {timings('always')} | {timings('gate')} | {num(t['median_ratio'],3)} | {t['argmax10_order_matches']} / {t['n']} |")
    d+=["","Четыре повтора одной фиксированной панели отражают разброс измерений на этой машине.","",
        "В препринте Adaptive Re-Ranking маршрутизатор учится выбирать между тремя моделями поиска по качеству и цене, авторы отдельно измеряют задержку и запас улучшения по oracle. В работе Optimal Re-Ranking Depth с SIGIR 2026 обычные оценки качества первой стадии слабо предсказывали оптимальную глубину второй. Наш эксперимент оценивает родственный вопрос в памяти агента на фиксированных исходных свидетельствах и использует точное покрытие эталонных диапазонов. Прямые сравнения с nDCG и задержкой на поисковых коллекциях потребуют самостоятельного прогона. [Genc et al., Adaptive Re-Ranking](https://arxiv.org/abs/2606.25249) · [Huo et al., Optimal Re-Ranking Depth](https://doi.org/10.1145/3805712.3809953)"]
    (ROOT/"REPORT_RU.md").write_bytes(("\n".join(d)+"\n").encode())


if __name__=="__main__":generate()
